import React from "react";
import { useTemplateData } from "../TemplateContext";
import { FacebookLogo, InstagramLogo, TwitterLogo } from "@phosphor-icons/react";

export default function Footer() {
  const data = useTemplateData();
  const [email, setEmail] = React.useState("");
  const [status, setStatus] = React.useState<"idle" | "success" | "error">("idle");

  const handleSubscribe = (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !/^\S+@\S+\.\S+$/.test(email)) {
      setStatus("error");
      return;
    }
    // Simulate successful subscription
    setStatus("success");
    setEmail("");
    setTimeout(() => setStatus("idle"), 3000);
  };

  return (
    <footer className="bg-[#3a2d2a] text-white pt-24 pb-12 relative z-0 mt-[-1px]">
      <div className="container mx-auto px-4 max-w-6xl">
        <div className="flex flex-col md:flex-row items-center justify-between gap-12 border-b border-white/10 pb-12 mb-12">

          <div className="flex-1 text-center md:text-left">
            <h4 className="font-serif text-xl mb-4 text-white">Follow Us</h4>
            <div className="flex justify-center md:justify-start items-center gap-4">
              <a href={data.footer.social.facebook} aria-label="Facebook" className="w-10 h-10 rounded-full bg-white text-[#3a2d2a] flex items-center justify-center hover:bg-[var(--color-primary)] hover:text-white hover:scale-110 transition-all duration-300">
                <FacebookLogo size={20} weight="fill" />
              </a>
              <a href={data.footer.social.instagram} aria-label="Instagram" className="w-10 h-10 rounded-full bg-white text-[#3a2d2a] flex items-center justify-center hover:bg-[var(--color-primary)] hover:text-white hover:scale-110 transition-all duration-300">
                <InstagramLogo size={20} weight="fill" />
              </a>
              <a href={data.footer.social.twitter} aria-label="Twitter" className="w-10 h-10 rounded-full bg-white text-[#3a2d2a] flex items-center justify-center hover:bg-[var(--color-primary)] hover:text-white hover:scale-110 transition-all duration-300">
                <TwitterLogo size={20} weight="fill" />
              </a>
            </div>
          </div>

          <div className="flex-1 flex justify-center">
             <div className="bg-[#3a2d2a] rounded-full p-4 shadow-lg border-2 border-dashed border-white/20 flex items-center justify-center w-32 h-32 relative">
              {data.brand.logo ? (
                <img src={data.brand.logo} alt={data.brand.name} className="w-full h-full object-contain relative z-10" />
              ) : (
                <div className="text-center relative z-10 leading-tight flex flex-col items-center justify-center">
                  <span className="font-serif text-2xl text-white block font-black" style={{ lineHeight: 1 }}>{data.brand.name.split(" ")[0]}</span>
                  <span className="font-sans text-[0.6rem] text-[var(--color-secondary)] uppercase tracking-widest font-bold mt-1">
                    {data.brand.name.split(" ").slice(1).join(" ")}
                  </span>
                </div>
              )}
            </div>
          </div>

          <div className="flex-1 text-center md:text-right">
            <h4 className="font-serif text-xl mb-4 text-white">Join Our Newsletter</h4>
            <form onSubmit={handleSubscribe} className="flex flex-col items-center md:items-end gap-2">
               <div className="flex w-full max-w-xs relative">
                 <input 
                   type="email" 
                   value={email}
                   onChange={(e) => { setEmail(e.target.value); setStatus("idle"); }}
                   placeholder="Your email address..." 
                   className={`w-full px-4 py-2 bg-white/10 text-white placeholder-gray-400 border rounded-l-md outline-none focus:border-[var(--color-primary)] ${status === 'error' ? 'border-red-500' : 'border-transparent'}`}
                 />
                 <button type="submit" className="bg-[var(--color-primary)] text-white px-4 py-2 rounded-r-md hover:bg-[var(--color-primary)]/90 transition-colors font-bold uppercase text-xs tracking-wider">
                   Subscribe
                 </button>
               </div>
               {status === "error" && <span className="text-red-400 text-xs">Please enter a valid email.</span>}
               {status === "success" && <span className="text-green-400 text-xs">Thank you for subscribing!</span>}
            </form>
          </div>

        </div>

        <div className="text-center">
          <p className="text-gray-400 text-xs font-semibold tracking-widest uppercase">
            {data.footer.copyright}
          </p>
        </div>
      </div>
    </footer>
  );
}

"use client";
import React from "react";
import { useTemplateData } from "../TemplateContext";
import { motion } from "framer-motion";
import { MagnifyingGlassPlus } from "@phosphor-icons/react";

export default function Gallery() {
  const data = useTemplateData();

  return (
    <section className="py-24 bg-white relative z-20">
      <div className="text-center mb-16">
        <div className="flex items-center justify-center gap-4 text-[var(--color-text)] mb-4">
          <svg className="w-16 h-2 text-[var(--color-secondary)]" viewBox="0 0 40 10" fill="currentColor">
            <path d="M0 5 Q10 0 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          </svg>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className="text-[var(--color-primary)]">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zM12 19.5c-4.14 0-7.5-3.36-7.5-7.5S7.86 4.5 12 4.5s7.5 3.36 7.5 7.5-3.36 7.5-7.5 7.5z" fill="currentColor"/>
            <circle cx="12" cy="12" r="4.5" fill="currentColor"/>
          </svg>
          <svg className="w-16 h-2 text-[var(--color-secondary)]" viewBox="0 0 40 10" fill="currentColor">
            <path d="M0 5 Q10 10 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          </svg>
        </div>
        <h2 className="font-serif text-4xl md:text-5xl text-[#3d3d3d] mb-4 tracking-wide">{data.gallery.title}</h2>
      </div>

      <div className="container mx-auto px-4 max-w-5xl">
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4 md:gap-6">
          {data.gallery.images.map((image, idx) => {
            return (
              <motion.div 
                key={idx}
                initial={{ opacity: 0, scale: 0.95 }}
                whileInView={{ opacity: 1, scale: 1 }}
                viewport={{ once: true, margin: "-50px" }}
                transition={{ duration: 0.6, delay: idx * 0.1, ease: "easeOut" }}
                className="rounded-xl overflow-hidden relative group aspect-square shadow-sm"
              >
                <img 
                  src={image} 
                  alt={`Creation ${idx + 1}`} 
                  className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 ease-out"
                />

                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300 flex items-center justify-center">
                  <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center text-[var(--color-primary)] scale-50 group-hover:scale-100 transition-all duration-300 delay-100">
                    <MagnifyingGlassPlus size={20} weight="bold" />
                  </div>
                </div>
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";
import React, { useState, useEffect } from "react";
import { useTemplateData } from "../TemplateContext";
import { List, MagnifyingGlass, ShoppingCart } from "@phosphor-icons/react";

export default function Header() {
  const data = useTemplateData();
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${scrolled ? 'bg-white shadow-md py-2' : 'bg-white/90 backdrop-blur-md py-4'} flex items-center justify-between`}>
      {/* Decorative wavy top border could be here, but let's keep it clean */}

      <div className="container mx-auto px-4 lg:px-8 flex items-center justify-between">

        <nav className="hidden md:flex items-center gap-8 text-sm font-bold tracking-widest uppercase text-[#3d3d3d] flex-1 justify-end pr-12">
          {data.navigation.links.slice(0, 3).map((link, idx) => (
            <a key={idx} href={link.href} className="hover:text-[var(--color-primary)] transition-colors duration-300 relative group">
              {link.label}
              <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-[var(--color-primary)] group-hover:w-full transition-all duration-300"></span>
            </a>
          ))}
        </nav>

        <div className="flex items-center justify-center relative z-50">
          {/* Brand/Logo */}
          <div className={`bg-white rounded-full p-4 shadow-sm border-2 border-dashed border-[var(--color-primary)] flex items-center justify-center transition-all duration-300 ${scrolled ? 'w-20 h-20' : 'w-28 h-28 md:w-32 md:h-32 -mb-16 shadow-lg'}`}>
            {data.brand.logo ? (
              <img src={data.brand.logo} alt={data.brand.name} className="w-full h-full object-contain relative z-10" />
            ) : (
              <div className="text-center relative z-10 leading-tight flex flex-col items-center justify-center">
                <span className="font-serif text-xl md:text-2xl text-[#3d3d3d] block font-black" style={{ lineHeight: 1 }}>{data.brand.name.split(" ")[0]}</span>
                <span className="font-sans text-[0.6rem] md:text-xs text-[var(--color-secondary)] uppercase tracking-widest font-bold mt-1">
                  {data.brand.name.split(" ").slice(1).join(" ")}
                </span>
              </div>
            )}
          </div>
        </div>

        <nav className="hidden md:flex items-center gap-8 text-sm font-bold tracking-widest uppercase text-[#3d3d3d] flex-1 justify-start pl-12">
          {data.navigation.links.slice(3).map((link, idx) => (
            <a key={idx} href={link.href} className="hover:text-[var(--color-primary)] transition-colors duration-300 relative group">
              {link.label}
              <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-[var(--color-primary)] group-hover:w-full transition-all duration-300"></span>
            </a>
          ))}
          <div className="flex items-center gap-4 ml-4">
            <button aria-label="Search" className="hover:text-[var(--color-primary)] transition-colors">
              <MagnifyingGlass size={20} weight="bold" />
            </button>
            <button aria-label="Cart" className="hover:text-[var(--color-primary)] transition-colors">
              <ShoppingCart size={20} weight="bold" />
            </button>
          </div>
        </nav>

        <button onClick={() => setMenuOpen(!menuOpen)} className="md:hidden text-[#3d3d3d] hover:text-[var(--color-primary)] ml-auto pr-4 relative z-50">
          <List size={28} weight="bold" />
        </button>

      </div>

      {/* Mobile Menu Overlay */}
      <div className={`fixed inset-0 bg-[#3a2d2a] text-white z-40 transition-transform duration-500 ease-in-out ${menuOpen ? 'translate-x-0' : 'translate-x-full'} md:hidden flex flex-col items-center justify-center`}>
        <nav className="flex flex-col items-center gap-8 text-xl font-serif">
          {data.navigation.links.map((link, idx) => (
            <a key={idx} href={link.href} onClick={() => setMenuOpen(false)} className="hover:text-[var(--color-primary)] transition-colors duration-300">
              {link.label}
            </a>
          ))}
        </nav>
      </div>
    </header>
  );
}

"use client";
import React from "react";
import { useTemplateData } from "../TemplateContext";
import { motion } from "framer-motion";

export default function Pricing() {
  const data = useTemplateData();

  const colors = ["var(--color-primary)", "var(--color-primary)", "var(--color-secondary)", "var(--color-primary)"];

  return (
    <section id="pricing" className="pt-24 pb-32 bg-white relative z-10">
      <div className="text-center mb-24">
        <div className="flex items-center justify-center gap-4 text-[var(--color-text)] mb-4">
          <svg className="w-16 h-2 text-[var(--color-secondary)]" viewBox="0 0 40 10" fill="currentColor">
            <path d="M0 5 Q10 0 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          </svg>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className="text-[var(--color-primary)]">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zM12 19.5c-4.14 0-7.5-3.36-7.5-7.5S7.86 4.5 12 4.5s7.5 3.36 7.5 7.5-3.36 7.5-7.5 7.5z" fill="currentColor"/>
            <circle cx="12" cy="12" r="4.5" fill="currentColor"/>
          </svg>
          <svg className="w-16 h-2 text-[var(--color-secondary)]" viewBox="0 0 40 10" fill="currentColor">
            <path d="M0 5 Q10 10 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          </svg>
        </div>
        <h2 className="text-4xl md:text-5xl font-serif text-[#3d3d3d] mb-4 tracking-wide">{data.pricing.title}</h2>
      </div>

      <div className="container mx-auto px-4 max-w-6xl">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
          {data.pricing.items.map((item, idx) => {
            const cardColor = colors[idx % colors.length];
            return (
              <motion.div 
                key={idx}
                initial={{ opacity: 0, y: 50 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-50px" }}
                transition={{ duration: 0.6, delay: idx * 0.1, ease: "easeOut" }}
                className="relative mt-16 group"
              >
                {/* Donut / Cake Graphic on top */}
                <div 
                  className="absolute -top-20 left-1/2 -translate-x-1/2 w-40 h-40 z-20 flex items-center justify-center transform group-hover:scale-110 group-hover:-translate-y-2 transition-all duration-500 rounded-full"
                >
                  <img src={item.image} alt={item.name} className="w-full h-full object-cover rounded-full mix-blend-multiply drop-shadow-xl" />
                  {/* Optional Featured Badge */}
                  {item.featured && (
                    <div className="absolute -right-2 top-8 bg-white border-2 border-[var(--color-primary)] text-[var(--color-primary)] font-bold text-xs uppercase px-3 py-1 rounded-full shadow-md rotate-12">
                      Best
                    </div>
                  )}
                </div>

                {/* Card Body */}
                <div className="bg-white border border-gray-100 rounded-lg overflow-hidden shadow-[0_15px_50px_-15px_rgba(0,0,0,0.1)] relative z-10 flex flex-col h-full text-center group-hover:shadow-[0_20px_60px_-15px_rgba(0,0,0,0.15)] transition-all duration-500">

                  {/* Colored dripping header area */}
                  <div 
                    className="pt-24 pb-6 relative z-20 transition-colors duration-500"
                    style={{ backgroundColor: cardColor }}
                  >
                    <h3 className="text-2xl font-serif text-white mb-2 relative z-10">{item.name}</h3>

                    {/* SVG dripping shape */}
                    <svg className="absolute top-[99%] left-0 w-full h-8" style={{ color: cardColor }} viewBox="0 0 100 20" preserveAspectRatio="none" fill="currentColor">
                      <path d="M0 0 L0 10 Q25 25 50 10 T100 10 L100 0 Z" />
                    </svg>
                  </div>

                  <div className="pt-8 pb-4 bg-white relative z-10">
                     <div className="text-5xl font-black text-[#3d3d3d] flex items-start justify-center">
                        <span className="text-4xl mt-1">{item.price}</span>
                        <span className="text-2xl mt-1">{item.currency}</span>
                      </div>
                      <div className="inline-block mt-4 text-xs font-bold uppercase px-4 py-1 rounded-full text-white tracking-widest" style={{ backgroundColor: cardColor }}>
                         For {item.name.includes("Cake") && !item.name.includes("Small") ? "1 Cake" : item.name.includes("Cupcake") ? "2 Cakes" : item.name.includes("Macaron") ? "5 Cakes" : "10 Cakes"}
                      </div>
                  </div>

                  {/* Features List */}
                  <div className="p-8 flex-grow flex flex-col justify-between">
                    <ul className="space-y-4 mb-8">
                      {item.features.map((feature, fIdx) => (
                        <li key={fIdx} className="text-sm text-gray-500 relative after:content-[''] after:block after:w-full after:h-[1px] after:bg-gray-100 after:mt-4 last:after:hidden">
                          {feature}
                        </li>
                      ))}
                    </ul>

                    <a 
                      href={item.buttonHref}
                      className="inline-block border border-[#3d3d3d] text-[#3d3d3d] hover:bg-[#3d3d3d] hover:text-white font-bold py-3 px-8 rounded-full transition-colors duration-300 uppercase tracking-widest text-xs"
                    >
                      {item.buttonLabel}
                    </a>
                  </div>
                </div>
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";
import React from "react";
import { useTemplateData } from "../TemplateContext";
import { motion } from "framer-motion";
import { Star, Coffee, Heart, Storefront } from "@phosphor-icons/react";

const getIcon = (iconName: string) => {
  switch (iconName) {
    case "Bread": return <Storefront size={24} weight="fill" />;
    case "Croissant": return <Coffee size={24} weight="fill" />;
    case "Cookie": return <Star size={24} weight="fill" />;
    case "Cake":
    default:
      return <Heart size={24} weight="fill" />;
  }
};

export default function Specialties() {
  const data = useTemplateData();

  return (
    <section id="specialties" className="py-24 bg-[#ffffff] relative z-20 overflow-hidden">

      <div className="text-center mb-20 relative z-10">
        <div className="flex items-center justify-center gap-4 text-[var(--color-text)] mb-4">
          <svg className="w-16 h-2 text-[var(--color-secondary)]" viewBox="0 0 40 10" fill="currentColor">
            <path d="M0 5 Q10 0 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          </svg>
          <Star size={28} weight="duotone" className="text-[var(--color-primary)]" />
          <svg className="w-16 h-2 text-[var(--color-secondary)]" viewBox="0 0 40 10" fill="currentColor">
            <path d="M0 5 Q10 10 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
          </svg>
        </div>
        <h2 className="font-serif text-4xl md:text-5xl text-[#3d3d3d] mb-4 tracking-wide">{data.specialties.title}</h2>
      </div>

      <div className="container mx-auto px-4 max-w-6xl relative z-10">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-12 lg:gap-8">
          {data.specialties.items.map((item, idx) => {
            return (
              <motion.div 
                key={idx}
                initial={{ opacity: 0, y: 30 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-50px" }}
                transition={{ duration: 0.6, delay: idx * 0.1, ease: "easeOut" }}
                className="flex flex-col items-center text-center group"
              >
                {/* Wavy/Scalloped Border Effect via SVG and layering */}
                <div className="relative w-48 h-48 mb-8 flex items-center justify-center">
                  {/* Decorative outer ring simulating the wavy border */}
                  <motion.div
                    animate={{ rotate: 360 }}
                    transition={{ duration: 40, repeat: Infinity, ease: "linear" }}
                    className="absolute inset-0 text-[var(--color-primary)] opacity-20"
                  >
                    <svg viewBox="0 0 100 100" className="w-full h-full fill-current">
                      <path d="M 50 0 C 58 0 62 5 70 8 C 78 11 85 8 90 15 C 95 22 92 29 95 37 C 98 45 102 52 98 59 C 94 66 90 69 85 76 C 80 83 75 88 67 92 C 59 96 52 100 44 98 C 36 96 29 92 22 88 C 15 84 9 79 5 72 C 1 65 0 58 2 50 C 4 42 0 35 4 28 C 8 21 14 16 21 11 C 28 6 35 2 43 0 Z" />
                    </svg>
                  </motion.div>

                  {/* Inner shape */}
                  <div className="absolute inset-2 bg-white rounded-full border-2 border-dashed border-[var(--color-primary)] z-10"></div>

                  {/* The Image inside the circle */}
                  <div className="absolute inset-4 rounded-full overflow-hidden z-20 bg-[var(--color-secondary)]">
                    <img 
                      src={item.image} 
                      alt={item.title} 
                      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 ease-out mix-blend-multiply"
                    />
                  </div>

                  {/* Icon badge */}
                  <div className="absolute -bottom-2 z-30 bg-white p-2 rounded-full shadow-md text-[var(--color-primary)] border border-gray-100 group-hover:-translate-y-2 transition-transform duration-300">
                    {getIcon(item.icon)}
                  </div>
                </div>

                <h3 className="text-xl font-bold font-serif text-[#3d3d3d] mb-3">{item.title}</h3>
                <p className="text-gray-500 mb-0 text-sm leading-relaxed max-w-[200px]">{item.description}</p>
              </motion.div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

"use client";
import React from "react";
import { useTemplateData } from "../TemplateContext";
import { motion } from "framer-motion";

export default function Testimonials() {
  const data = useTemplateData();

  return (
    <section className="py-24 bg-[var(--color-secondary)] relative z-20 overflow-hidden text-center">
      <div className="absolute inset-0 bg-white/10" style={{ backgroundImage: 'radial-gradient(white 1px, transparent 1px)', backgroundSize: '30px 30px', opacity: 0.2 }}></div>

      <div className="container mx-auto px-4 max-w-4xl relative z-10">
        <div className="text-center mb-16">
          <div className="flex items-center justify-center gap-4 text-white mb-4">
            <svg className="w-16 h-2 text-white/50" viewBox="0 0 40 10" fill="currentColor">
              <path d="M0 5 Q10 0 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
            </svg>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" className="text-white">
              <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zM12 19.5c-4.14 0-7.5-3.36-7.5-7.5S7.86 4.5 12 4.5s7.5 3.36 7.5 7.5-3.36 7.5-7.5 7.5z" fill="currentColor"/>
              <circle cx="12" cy="12" r="4.5" fill="currentColor"/>
            </svg>
            <svg className="w-16 h-2 text-white/50" viewBox="0 0 40 10" fill="currentColor">
              <path d="M0 5 Q10 10 20 5 T40 5" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
            </svg>
          </div>
          <h2 className="font-serif text-4xl md:text-5xl text-white mb-4 tracking-wide">{data.testimonials.title}</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {data.testimonials.items.map((item, idx) => (
            <motion.div 
              key={idx}
              initial={{ opacity: 0, y: 30 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true, margin: "-50px" }}
              transition={{ duration: 0.6, delay: idx * 0.1, ease: "easeOut" }}
              className="flex flex-col items-center"
            >
              <div className="w-20 h-20 rounded-full overflow-hidden border-4 border-white shadow-lg mb-6 relative">
                <img 
                  src={item.avatar} 
                  alt={item.name} 
                  className="w-full h-full object-cover"
                />
              </div>

              <div className="flex gap-1 text-white mb-6 justify-center">
                {[1,2,3,4,5].map(star => (
                  <svg key={star} className="w-4 h-4 fill-current drop-shadow-sm" viewBox="0 0 20 20">
